var privacyPage = /* @__PURE__ */ __name((iconDataUrl) => shell("\uAC1C\uC778\uC815\uBCF4 \uCC98\uB9AC\uBC29\uCE68", `<main class="doc-page"><article class="document"><h1>\uAC1C\uC778\uC815\uBCF4 \uCC98\uB9AC\uBC29\uCE68</h1><p>\uC2DC\uD589\uC77C: 2026\uB144 7\uC6D4 14\uC77C</p><h2>\uCC98\uB9AC\uD558\uB294 \uC815\uBCF4</h2><p>\uB531\uB2F4\uC544\uB294 \uBE44\uBC00\uBC88\uD638, \uCE74\uB4DC\uBC88\uD638, \uACB0\uC81C\uC218\uB2E8, \uCFE0\uD321 \uC138\uC158 \uCFE0\uD0A4 \uC6D0\uBB38\uC744 \uC218\uC9D1\uD558\uAC70\uB098 \uC800\uC7A5\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC5F0\uACB0\uC744 \uC704\uD574 \uC77C\uD68C\uC131 \uCF54\uB4DC\uC640 \uAE30\uAE30 \uC5F0\uACB0 \uC815\uBCF4, \uC0AC\uC6A9\uC790\uAC00 \uC804\uC1A1\uD55C \uC1FC\uD551 \uBAA9\uB85D\uACFC \uCC98\uB9AC \uC0C1\uD0DC\uB97C \uD544\uC694\uD55C \uAE30\uAC04\uC5D0 \uD55C\uD574 \uCC98\uB9AC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.</p><h2>\uBCF4\uAD00 \uAE30\uAC04</h2><ul><li>\uC77C\uD68C\uC131 \uC5F0\uACB0 \uCF54\uB4DC: \uCD5C\uB300 10\uBD84</li><li>\uC7A5\uBC14\uAD6C\uB2C8 \uACC4\uD68D \uC804\uC1A1 \uB370\uC774\uD130: \uCD5C\uB300 15\uBD84</li><li>\uAE30\uAE30 \uC5F0\uACB0 \uC815\uBCF4: \uCD5C\uB300 30\uC77C \uB610\uB294 \uC5F0\uACB0 \uD574\uC81C \uC2DC\uC810\uAE4C\uC9C0</li><li>\uC9C0\uC6D0 \uBB38\uC758: \uC811\uC218\uC77C\uB85C\uBD80\uD130 \uCD5C\uB300 30\uC77C</li></ul><h2>\uC678\uBD80 \uC11C\uBE44\uC2A4</h2><p>\uC0C1\uD488 \uAC80\uC0C9\uACFC \uC7A5\uBC14\uAD6C\uB2C8 \uCC98\uB9AC\uB294 \uC0AC\uC6A9\uC790\uC758 \uBE0C\uB77C\uC6B0\uC800\uC5D0\uC11C \uCFE0\uD321 \uD398\uC774\uC9C0\uB97C \uD1B5\uD574 \uC774\uB8E8\uC5B4\uC9D1\uB2C8\uB2E4. ChatGPT \uC571 \uAE30\uB2A5\uC740 OpenAI \uC11C\uBE44\uC2A4\uC640 \uC5F0\uB3D9\uB420 \uC218 \uC788\uC73C\uBA70, \uACF5\uAC1C \uC11C\uBC84\uB294 Cloudflare Workers\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4.</p><h2>\uBB38\uC758\uC640 \uC0AD\uC81C</h2><p>\uD655\uC7A5 \uD504\uB85C\uADF8\uB7A8\uC5D0\uC11C \uC5F0\uACB0 \uD574\uC81C\uB97C \uC2E4\uD589\uD558\uBA74 \uD574\uB2F9 \uAE30\uAE30\uC758 \uC5F0\uACB0 \uD1A0\uD070\uACFC \uB300\uAE30 \uC911\uC778 \uACC4\uD68D \uB370\uC774\uD130\uAC00 \uC0AD\uC81C\uB429\uB2C8\uB2E4. \uAC1C\uC778\uC815\uBCF4 \uAD00\uB828 \uBB38\uC758\uB294 \uC9C0\uC6D0 \uD398\uC774\uC9C0\uB97C \uC774\uC6A9\uD574 \uC8FC\uC138\uC694.</p></article></main>`, iconDataUrl), "privacyPage");
var termsPage = /* @__PURE__ */ __name((iconDataUrl) => shell("\uC774\uC6A9\uC57D\uAD00", `<main class="doc-page"><article class="document"><h1>\uC774\uC6A9\uC57D\uAD00</h1><p>\uC2DC\uD589\uC77C: 2026\uB144 7\uC6D4 14\uC77C</p><h2>\uC11C\uBE44\uC2A4 \uBC94\uC704</h2><p>\uB531\uB2F4\uC544\uB294 \uC1FC\uD551 \uBAA9\uB85D \uBD84\uC11D, \uD6C4\uBCF4 \uBE44\uAD50, \uC0AC\uC6A9\uC790 \uD655\uC778 \uD6C4 \uC7A5\uBC14\uAD6C\uB2C8 \uCD94\uAC00\uB97C \uB3D5\uB294 \uBCF4\uC870 \uC11C\uBE44\uC2A4\uC785\uB2C8\uB2E4.</p><h2>\uC0AC\uC6A9\uC790 \uD655\uC778</h2><p>\uAC00\uACA9, \uC7AC\uACE0, \uBC30\uC1A1\uBE44, \uC635\uC158\uACFC \uCD5C\uC885 \uC8FC\uBB38 \uAE08\uC561\uC740 \uBCC0\uB3D9\uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC0AC\uC6A9\uC790\uB294 \uACB0\uC81C \uC804\uC5D0 \uCFE0\uD321 \uC7A5\uBC14\uAD6C\uB2C8\uC640 \uC8FC\uBB38 \uD654\uBA74\uC758 \uC815\uBCF4\uB97C \uC9C1\uC811 \uD655\uC778\uD574\uC57C \uD569\uB2C8\uB2E4.</p><h2>\uAE08\uC9C0 \uC0AC\uD56D</h2><p>\uBCF4\uC548 \uD655\uC778 \uC6B0\uD68C, \uBE44\uC815\uC0C1\uC801 \uB300\uB7C9 \uC694\uCCAD, \uB2E4\uB978 \uC0AC\uB78C\uC758 \uACC4\uC815\uC774\uB098 \uC5F0\uACB0 \uCF54\uB4DC \uBB34\uB2E8 \uC0AC\uC6A9\uC740 \uAE08\uC9C0\uB429\uB2C8\uB2E4.</p><h2>\uCC45\uC784 \uC81C\uD55C</h2><p>\uB531\uB2F4\uC544\uB294 \uC790\uB3D9 \uACB0\uC81C\uB098 \uC8FC\uBB38 \uD655\uC815\uC744 \uC2E4\uD589\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uD45C\uC2DC\uB41C \uC815\uBCF4 \uB610\uB294 \uB9C1\uD06C\uB9CC\uC73C\uB85C \uAD6C\uB9E4 \uACB0\uACFC\uAC00 \uBCF4\uC7A5\uB418\uC9C0\uB294 \uC54A\uC2B5\uB2C8\uB2E4.</p></article></main>`, iconDataUrl), "termsPage");
